import * as THREE from "three";

// Primary swell travels toward +x. phase = k*x - w*t.
// The rider locks to phaseOnFace so the board stays on the steep face
// while the mesh scrolls backward in the ride frame.
export const WAVE = {
  k: 0.34,
  w: 1.45,
  phaseOnFace: Math.PI / 2 - 1.15,
  A: 1.05,
  harmonic: 0.38,
};

const _tx = new THREE.Vector3();
const _tz = new THREE.Vector3();

export function waveHeight(x, z, t) {
  const p = x * WAVE.k - t * WAVE.w;
  let y = Math.sin(p) + WAVE.harmonic * Math.sin(2 * p + 0.85);
  y *= WAVE.A;
  y += 0.055 * Math.sin(z * 0.42 + t * 0.7);
  y += 0.04 * Math.sin(x * 0.15 + z * 0.28 - t * 1.25);
  return y;
}

// Writes an upward normal. Flat check: +x tangent × +z tangent is -y in
// y-up right-handed space, so the normal is tangentZ × tangentX.
export function writeWaveNormal(x, z, t, out) {
  const e = 0.22;
  _tx.set(2 * e, waveHeight(x + e, z, t) - waveHeight(x - e, z, t), 0);
  _tz.set(0, waveHeight(x, z + e, t) - waveHeight(x, z - e, t), 2 * e);
  return out.crossVectors(_tz, _tx).normalize();
}

export function rideState(t, outNormal) {
  const x = (WAVE.phaseOnFace + WAVE.w * t) / WAVE.k;
  const zFreq = 0.48;
  const zAmp = 1.15;
  const z = Math.sin(t * zFreq) * zAmp;
  const vz = Math.cos(t * zFreq) * zAmp * zFreq;
  const vx = WAVE.w / WAVE.k;
  const y = waveHeight(x, z, t);
  writeWaveNormal(x, z, t, outNormal);
  return { x, y, z, vx, vz };
}

import * as THREE from "three";

const _f = new THREE.Vector3();
const _u = new THREE.Vector3();
const _r = new THREE.Vector3();
const _f2 = new THREE.Vector3();
const _u2 = new THREE.Vector3();
const _m = new THREE.Matrix4();
const _fallback = new THREE.Vector3();

// Local -z becomes `forward`, local +y becomes `up`.
// Canonical: forward (0,0,-1), up (0,1,0) → right (1,0,0), because forward × up = right.
export function quaternionFacing(forward, up, target) {
  _f.copy(forward).normalize();
  _u.copy(up).normalize();
  _r.crossVectors(_f, _u);
  if (_r.lengthSq() < 1e-8) {
    _fallback.set(1, 0, 0);
    _r.crossVectors(_f, _fallback);
    if (_r.lengthSq() < 1e-8) {
      _fallback.set(0, 0, 1);
      _r.crossVectors(_f, _fallback);
    }
  }
  _r.normalize();
  // up × right = forward, rebuilt so the axes stay orthonormal.
  _f2.crossVectors(_u, _r).normalize();
  _u2.crossVectors(_r, _f2).normalize();
  // Object3D local forward is -z, so the matrix z column is -forward.
  _m.makeBasis(_r, _u2, _f2.clone().negate());
  target.setFromRotationMatrix(_m);
  return target;
}

import * as THREE from "three";
import { rideState } from "./wave.js";
import { quaternionFacing } from "./frame.js";

const _normal = new THREE.Vector3();
const _fwd = new THREE.Vector3();
const _up = new THREE.Vector3();
const _worldUp = new THREE.Vector3(0, 1, 0);

// Keeps the rider near the origin. `originX` is the world scroll passed to the ocean.
export function placeRider(object, t) {
  const state = rideState(t, _normal);
  const speed = Math.hypot(state.vx, state.vz);
  const turn = state.vz / speed;

  _fwd.set(state.vx, 0, state.vz).normalize();
  // Soften the surface normal so the bird stays readable on the steep face.
  _up.copy(_normal).lerp(_worldUp, 0.34).normalize();
  _fwd.addScaledVector(_up, -_fwd.dot(_up));
  if (_fwd.lengthSq() < 1e-8) _fwd.set(1, 0, 0);
  _fwd.normalize();

  // Positive turn (velocity toward the bird's right, +z) rolls the right wing down.
  // Positive rotation about forward raises the right side, so the bank angle is negated.
  _up.applyAxisAngle(_fwd, -turn * 0.75);

  quaternionFacing(_fwd, _up, object.quaternion);
  object.position.set(0, state.y, state.z);
  object.position.addScaledVector(_normal, 0.2);

  return {
    originX: state.x,
    y: state.y,
    z: state.z,
    vx: state.vx,
    vz: state.vz,
    speed,
    turn,
  };
}

