import * as THREE from "three";

const palette = {
  body: 0x6d5344,
  bodyDark: 0x3a2d28,
  chest: 0xf4ecdf,
  head: 0xf7f3ea,
  beak: 0xf0b24a,
  beakRidge: 0xc9843a,
  pouch: 0xd98468,
  foot: 0xd08a52,
  board: 0xf2c94b,
  boardDark: 0xd9a63a,
  pad: 0x2c2826,
  fin: 0xef5d3f,
  stringer: 0xfff8ea,
  iris: 0xf2d27a,
  pupil: 0x1a120e,
};

function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: opts.roughness ?? 0.72,
    metalness: opts.metalness ?? 0,
    envMapIntensity: opts.envMapIntensity ?? 0.35,
    vertexColors: opts.vertexColors ?? false,
    side: opts.side ?? THREE.FrontSide,
  });
}

function solid(geo, material) {
  const mesh = new THREE.Mesh(geo, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

// Shape is drawn in XY. +Y becomes local -Z (forward), extrude +Z becomes +Y (up).
function layFlat(geo) {
  geo.rotateX(-Math.PI / 2);
  geo.computeVertexNormals();
  return geo;
}

function boardGeometry() {
  const s = new THREE.Shape();
  const nose = 1.32;
  const tail = -1.02;
  s.moveTo(0, nose);
  s.bezierCurveTo(0.18, 0.95, 0.3, 0.45, 0.3, 0.05);
  s.bezierCurveTo(0.3, -0.4, 0.2, tail + 0.25, 0.1, tail);
  s.quadraticCurveTo(0, tail - 0.05, -0.1, tail);
  s.bezierCurveTo(-0.2, tail + 0.25, -0.3, -0.4, -0.3, 0.05);
  s.bezierCurveTo(-0.3, 0.45, -0.18, 0.95, 0, nose);
  const geo = new THREE.ExtrudeGeometry(s, {
    depth: 0.065,
    bevelEnabled: true,
    bevelThickness: 0.012,
    bevelSize: 0.014,
    bevelSegments: 2,
  });
  layFlat(geo);
  geo.computeBoundingBox();
  geo.translate(0, 0.02 - geo.boundingBox.min.y, 0);
  return geo;
}

function wingGeometry() {
  const s = new THREE.Shape();
  s.moveTo(0.02, 0.04);
  s.bezierCurveTo(0.15, 0.22, 0.55, 0.26, 1.05, 0.14);
  s.bezierCurveTo(1.35, 0.08, 1.52, 0.03, 1.62, 0.0);
  s.bezierCurveTo(1.28, -0.03, 1.05, -0.14, 0.62, -0.16);
  s.quadraticCurveTo(0.22, -0.1, 0.02, 0.04);
  const geo = new THREE.ExtrudeGeometry(s, {
    depth: 0.028,
    bevelEnabled: true,
    bevelThickness: 0.006,
    bevelSize: 0.006,
    bevelSegments: 1,
  });
  layFlat(geo);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const near = new THREE.Color(0x7a5b4a);
  const far = new THREE.Color(0x2a221e);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const span = THREE.MathUtils.clamp(pos.getX(i) / 1.62, 0, 1);
    c.copy(near).lerp(far, Math.pow(span, 1.35));
    colors[i * 3] = c.r;
    colors[i * 3 + 1] = c.g;
    colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  return geo;
}

function mirrorSpan(geo) {
  const g = geo.clone();
  const p = g.attributes.position;
  for (let i = 0; i < p.count; i++) p.setX(i, -p.getX(i));
  g.computeVertexNormals();
  const n = g.attributes.normal;
  let sum = 0;
  for (let i = 0; i < n.count; i++) sum += n.getY(i);
  if (sum < 0) {
    for (let i = 0; i < n.count; i++) {
      n.setXYZ(i, -n.getX(i), -n.getY(i), -n.getZ(i));
    }
  }
  return g;
}

function tailGeometry() {
  const s = new THREE.Shape();
  s.moveTo(0, 0.02);
  s.lineTo(0.16, -0.34);
  s.lineTo(0.05, -0.28);
  s.lineTo(0, -0.46);
  s.lineTo(-0.05, -0.28);
  s.lineTo(-0.16, -0.34);
  s.lineTo(0, 0.02);
  const geo = new THREE.ExtrudeGeometry(s, { depth: 0.02, bevelEnabled: false });
  return layFlat(geo);
}

function footGeometry() {
  const s = new THREE.Shape();
  s.moveTo(0, 0.02);
  s.lineTo(0.1, 0.2);
  s.lineTo(0.03, 0.16);
  s.lineTo(0, 0.28);
  s.lineTo(-0.03, 0.16);
  s.lineTo(-0.1, 0.2);
  s.lineTo(0, 0.02);
  const geo = new THREE.ExtrudeGeometry(s, { depth: 0.018, bevelEnabled: false });
  return layFlat(geo);
}

export function createPelican() {
  const root = new THREE.Group();
  root.name = "pelican";

  const board = solid(boardGeometry(), mat(palette.board, { roughness: 0.48, envMapIntensity: 0.45 }));
  root.add(board);

  const pad = solid(
    new THREE.BoxGeometry(0.26, 0.012, 0.42),
    mat(palette.pad, { roughness: 0.9 }),
  );
  pad.position.set(0, 0.1, 0.28);
  root.add(pad);

  const stringer = solid(
    new THREE.BoxGeometry(0.02, 0.01, 1.7),
    mat(palette.stringer, { roughness: 0.4 }),
  );
  stringer.position.set(0, 0.1, -0.05);
  root.add(stringer);

  const fin = solid(
    new THREE.BoxGeometry(0.025, 0.16, 0.2),
    mat(palette.fin, { roughness: 0.4, envMapIntensity: 0.5 }),
  );
  fin.position.set(0, -0.02, 0.72);
  fin.rotation.x = -0.25;
  root.add(fin);

  const bodyMat = mat(palette.body, { roughness: 0.78 });
  const body = solid(new THREE.SphereGeometry(1, 28, 20), bodyMat);
  body.scale.set(0.34, 0.27, 0.5);
  body.position.set(0, 0.4, 0.02);
  body.rotation.x = 0.22;
  root.add(body);

  const chest = solid(new THREE.SphereGeometry(1, 20, 16), mat(palette.chest, { roughness: 0.7 }));
  chest.scale.set(0.24, 0.2, 0.26);
  chest.position.set(0, 0.36, -0.22);
  root.add(chest);

  const back = solid(new THREE.SphereGeometry(1, 18, 14), mat(palette.bodyDark, { roughness: 0.8 }));
  back.scale.set(0.22, 0.12, 0.28);
  back.position.set(0, 0.58, 0.08);
  root.add(back);

  const neck1 = new THREE.Group();
  neck1.position.set(0, 0.5, -0.28);
  root.add(neck1);
  const neck1Mesh = solid(
    new THREE.CylinderGeometry(0.075, 0.09, 0.34, 12),
    mat(palette.chest, { roughness: 0.68 }),
  );
  neck1Mesh.rotation.x = -Math.PI / 2;
  neck1Mesh.position.z = -0.17;
  neck1.add(neck1Mesh);

  const neck2 = new THREE.Group();
  neck2.position.set(0, 0, -0.34);
  neck1.add(neck2);
  const neck2Mesh = solid(
    new THREE.CylinderGeometry(0.06, 0.075, 0.28, 12),
    mat(palette.head, { roughness: 0.62 }),
  );
  neck2Mesh.rotation.x = -Math.PI / 2;
  neck2Mesh.position.z = -0.14;
  neck2.add(neck2Mesh);

  const head = new THREE.Group();
  head.position.set(0, 0.02, -0.28);
  neck2.add(head);
  const skull = solid(new THREE.SphereGeometry(0.16, 20, 16), mat(palette.head, { roughness: 0.55 }));
  skull.scale.set(1, 0.92, 1.08);
  head.add(skull);

  const crown = solid(new THREE.SphereGeometry(0.1, 14, 12), mat(palette.bodyDark, { roughness: 0.75 }));
  crown.scale.set(0.85, 0.55, 1.1);
  crown.position.set(0, 0.1, 0.04);
  head.add(crown);

  const beak = new THREE.Group();
  beak.position.set(0, -0.02, -0.1);
  head.add(beak);
  const billLen = 0.72;
  const bill = solid(
    new THREE.CylinderGeometry(0.02, 0.055, billLen, 10),
    mat(palette.beak, { roughness: 0.38, envMapIntensity: 0.55 }),
  );
  bill.rotation.x = -Math.PI / 2;
  bill.position.z = -billLen / 2;
  beak.add(bill);

  const ridge = solid(
    new THREE.CylinderGeometry(0.012, 0.03, billLen * 0.92, 8),
    mat(palette.beakRidge, { roughness: 0.42 }),
  );
  ridge.rotation.x = -Math.PI / 2;
  ridge.position.set(0, 0.028, -billLen * 0.46);
  beak.add(ridge);

  const hook = solid(
    new THREE.ConeGeometry(0.028, 0.09, 8),
    mat(palette.beakRidge, { roughness: 0.4 }),
  );
  hook.rotation.x = Math.PI * 0.92;
  hook.position.set(0, -0.02, -billLen + 0.02);
  beak.add(hook);

  const pouch = solid(new THREE.SphereGeometry(1, 16, 12), mat(palette.pouch, { roughness: 0.62 }));
  pouch.scale.set(0.09, 0.07, 0.3);
  pouch.position.set(0, -0.06, -0.34);
  beak.add(pouch);

  const beakTip = new THREE.Object3D();
  beakTip.name = "beakTip";
  beakTip.position.set(0, -0.03, -billLen);
  beak.add(beakTip);

  function eye(side) {
    const g = new THREE.Group();
    g.position.set(0.105 * side, 0.03, -0.06);
    const ring = solid(new THREE.SphereGeometry(0.048, 12, 10), mat(palette.bodyDark, { roughness: 0.5 }));
    const iris = solid(new THREE.SphereGeometry(0.034, 12, 10), mat(palette.iris, { roughness: 0.35 }));
    iris.position.x = 0.02 * side;
    const pupil = solid(new THREE.SphereGeometry(0.018, 10, 8), mat(palette.pupil, { roughness: 0.3 }));
    pupil.position.x = 0.038 * side;
    const shine = solid(new THREE.SphereGeometry(0.008, 8, 6), mat(0xffffff, { roughness: 0.2 }));
    shine.position.set(0.046 * side, 0.012, -0.01);
    g.add(ring, iris, pupil, shine);
    return g;
  }
  const eyeR = eye(1);
  const eyeL = eye(-1);
  head.add(eyeR, eyeL);

  const wingMat = mat(0xffffff, {
    roughness: 0.78,
    vertexColors: true,
    side: THREE.DoubleSide,
  });
  const wingGeoR = wingGeometry();
  const wingR = new THREE.Group();
  wingR.position.set(0.18, 0.52, -0.02);
  wingR.add(solid(wingGeoR, wingMat));
  root.add(wingR);

  const wingL = new THREE.Group();
  wingL.position.set(-0.18, 0.52, -0.02);
  wingL.add(solid(mirrorSpan(wingGeoR), wingMat));
  root.add(wingL);

  const tail = new THREE.Group();
  tail.position.set(0, 0.4, 0.42);
  tail.add(solid(tailGeometry(), mat(palette.bodyDark, { roughness: 0.8, side: THREE.DoubleSide })));
  root.add(tail);

  const footMat = mat(palette.foot, { roughness: 0.6, side: THREE.DoubleSide });
  const footGeo = footGeometry();
  function limb(side) {
    const leg = solid(new THREE.CylinderGeometry(0.03, 0.038, 0.18, 8), footMat);
    leg.position.set(0.14 * side, 0.2, 0.16);
    root.add(leg);
    const foot = solid(footGeo, footMat);
    foot.position.set(0.14 * side, 0.105, 0.1);
    root.add(foot);
  }
  limb(1);
  limb(-1);

  function update(t, turn) {
    const flap = Math.sin(t * 1.15) * 0.1 + Math.sin(t * 2.5) * 0.03;
    const roll = -turn * 0.2;
    wingR.rotation.z = 0.28 + flap + roll;
    wingL.rotation.z = -0.28 - flap + roll;
    wingR.rotation.y = 0.18;
    wingL.rotation.y = -0.18;
    neck1.rotation.x = 0.78 + Math.sin(t * 2.05) * 0.045;
    neck2.rotation.x = -0.55 + Math.sin(t * 2.05 + 0.7) * 0.04;
    head.rotation.x = -0.12 + Math.sin(t * 2.05 + 0.2) * 0.03;
    head.rotation.y = Math.sin(t * 0.55) * 0.07;
    tail.rotation.x = -0.55 + Math.sin(t * 2.8) * 0.06;
    tail.rotation.y = -turn * 0.45;
    const blink = Math.pow(Math.max(0, Math.sin(t * 0.62)), 48);
    const squish = 1 - blink * 0.9;
    eyeR.scale.y = squish;
    eyeL.scale.y = squish;
  }

  return { root, update, beakTip, head, wingGeoR };
}

import * as THREE from "three";

export const SUN_DIR = new THREE.Vector3(0.48, 0.58, -0.34).normalize();

const HORIZON = new THREE.Color("#f3b48a");
const ZENITH = new THREE.Color("#6aa6dc");
const NADIR = new THREE.Color("#e7c4a4");

export function createSky() {
  const geo = new THREE.SphereGeometry(180, 28, 16);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    fog: false,
    depthWrite: false,
    uniforms: {
      sunDir: { value: SUN_DIR },
      horizon: { value: HORIZON },
      zenith: { value: ZENITH },
      nadir: { value: NADIR },
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vec4 worldPos = modelMatrix * vec4(position, 1.0);
        vDir = worldPos.xyz - cameraPosition;
        gl_Position = projectionMatrix * viewMatrix * worldPos;
      }
    `,
    fragmentShader: `
      varying vec3 vDir;
      uniform vec3 sunDir;
      uniform vec3 horizon;
      uniform vec3 zenith;
      uniform vec3 nadir;
      void main() {
        vec3 d = normalize(vDir);
        float h = d.y;
        vec3 col = mix(nadir, horizon, smoothstep(-0.25, 0.06, h));
        col = mix(col, zenith, smoothstep(0.0, 0.72, h));
        float sun = pow(max(dot(d, sunDir), 0.0), 320.0);
        float glow = pow(max(dot(d, sunDir), 0.0), 7.0);
        col += vec3(1.0, 0.92, 0.78) * sun * 1.5;
        col += vec3(1.0, 0.68, 0.42) * glow * 0.38;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const dome = new THREE.Mesh(geo, mat);
  dome.frustumCulled = false;
  dome.renderOrder = -1;

  const clouds = new THREE.Group();
  const puffGeo = new THREE.SphereGeometry(1, 12, 10);
  const puffMat = new THREE.MeshBasicMaterial({
    color: 0xfff4ea,
    transparent: true,
    opacity: 0.82,
    fog: false,
    depthWrite: false,
  });
  const banks = [
    { x: -30, y: 16, z: -18, s: 3.2 },
    { x: 8, y: 18, z: -28, s: 4.1 },
    { x: 36, y: 14, z: -8, s: 2.4 },
    { x: -12, y: 20, z: 24, s: 2.8 },
    { x: 22, y: 17, z: 18, s: 3.4 },
  ];
  const movers = [];
  for (const bank of banks) {
    const g = new THREE.Group();
    const blobs = [
      [0, 0, 0, 1],
      [0.9, 0.15, 0.2, 0.75],
      [-0.85, 0.05, -0.1, 0.7],
      [0.3, 0.35, -0.15, 0.62],
    ];
    for (const [x, y, z, s] of blobs) {
      const puff = new THREE.Mesh(puffGeo, puffMat);
      puff.position.set(x * bank.s, y * bank.s, z * bank.s);
      puff.scale.setScalar(s * bank.s);
      g.add(puff);
    }
    g.userData.x0 = bank.x;
    g.userData.phase = bank.x;
    g.position.set(bank.x, bank.y, bank.z);
    clouds.add(g);
    movers.push(g);
  }

  function update(t) {
    for (const g of movers) {
      const span = 150;
      g.position.x = ((g.userData.x0 - t * 1.4) % span + span) % span - span / 2;
    }
  }

  return { dome, clouds, update, horizon: HORIZON };
}

import * as THREE from "three";
import { waveHeight } from "./wave.js";
import { SUN_DIR } from "./sky.js";

function smoothstep(edge0, edge1, x) {
  const t = THREE.MathUtils.clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

export function createOcean() {
  const geo = new THREE.PlaneGeometry(100, 80, 120, 90);
  geo.rotateX(-Math.PI / 2);
  const colors = new Float32Array(geo.attributes.position.count * 3);
  geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));

  const material = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.3,
    metalness: 0.05,
    envMapIntensity: 0.65,
  });
  const mesh = new THREE.Mesh(geo, material);
  mesh.receiveShadow = true;
  mesh.castShadow = false;

  const deep = new THREE.Color("#083e4c");
  const mid = new THREE.Color("#1597a0");
  const lit = new THREE.Color("#8ae6d4");
  const foam = new THREE.Color("#f6f3ee");
  const glint = new THREE.Color("#fff4d8");
  const col = new THREE.Color();

  function update(t, originX) {
    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i) + originX;
      const z = pos.getZ(i);
      pos.setY(i, waveHeight(x, z, t));
    }
    pos.needsUpdate = true;
    geo.computeVertexNormals();
    const nrm = geo.attributes.normal;
    for (let i = 0; i < pos.count; i++) {
      const h = pos.getY(i);
      const nx = nrm.getX(i);
      const ny = nrm.getY(i);
      const nz = nrm.getZ(i);
      const nd = Math.max(0, nx * SUN_DIR.x + ny * SUN_DIR.y + nz * SUN_DIR.z);
      const crest = smoothstep(0.45, 1.2, h);
      const steep = smoothstep(0.08, 0.4, 1 - ny);
      const foamAmt = Math.min(1, crest * 0.92 + crest * steep * 0.45);
      const mix = THREE.MathUtils.clamp(0.2 + (h + 0.4) * 0.38 + nd * 0.25, 0, 1);
      col.copy(deep).lerp(mid, mix);
      col.lerp(lit, nd * 0.4);
      col.lerp(foam, foamAmt);
      col.lerp(glint, Math.pow(nd, 28) * 0.85);
      colors[i * 3] = col.r;
      colors[i * 3 + 1] = col.g;
      colors[i * 3 + 2] = col.b;
    }
    geo.attributes.color.needsUpdate = true;
  }

  return { mesh, update };
}

import * as THREE from "three";

function dropletTexture() {
  const canvas = document.createElement("canvas");
  canvas.width = 64;
  canvas.height = 64;
  const g = canvas.getContext("2d");
  const grd = g.createRadialGradient(32, 32, 2, 32, 32, 30);
  grd.addColorStop(0, "rgba(255,255,255,0.95)");
  grd.addColorStop(0.35, "rgba(236,248,255,0.55)");
  grd.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grd;
  g.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function createSpray() {
  const map = dropletTexture();
  const group = new THREE.Group();
  const count = 64;
  const drops = [];
  for (let i = 0; i < count; i++) {
    const material = new THREE.SpriteMaterial({
      map,
      transparent: true,
      depthWrite: false,
      opacity: 0,
      color: 0xf7fbff,
    });
    const sprite = new THREE.Sprite(material);
    sprite.visible = false;
    sprite.scale.setScalar(0.2);
    group.add(sprite);
    drops.push({
      sprite,
      life: 0,
      age: 1,
      vel: new THREE.Vector3(),
    });
  }

  const forward = new THREE.Vector3();
  const right = new THREE.Vector3();
  const up = new THREE.Vector3();
  const tail = new THREE.Vector3();
  let cursor = 0;

  function emit(rider, speed) {
    const drop = drops[cursor];
    cursor = (cursor + 1) % drops.length;
    forward.set(0, 0, -1).applyQuaternion(rider.quaternion);
    right.set(1, 0, 0).applyQuaternion(rider.quaternion);
    up.set(0, 1, 0).applyQuaternion(rider.quaternion);
    tail.set(0.2 + Math.random() * 0.08, 0.04, 0.85 + Math.random() * 0.2);
    tail.applyQuaternion(rider.quaternion).add(rider.position);
    drop.sprite.position.copy(tail);
    drop.sprite.visible = true;
    drop.life = 0.75 + Math.random() * 0.35;
    drop.age = drop.life;
    // Water is still in the world; the ride frame scrolls forward at `speed`,
    // so a fresh droplet trails toward -x and is kicked up off the rail.
    drop.vel.set(-speed * (0.85 + Math.random() * 0.2), 0, (Math.random() - 0.5) * 0.35);
    drop.vel.addScaledVector(up, 1.3 + Math.random() * 1.7);
    drop.vel.addScaledVector(right, 0.35 + Math.random() * 0.9);
    drop.vel.addScaledVector(forward, -Math.random() * 0.5);
  }

  function update(dt, rider, speed) {
    const births = dt > 0 ? 3 : 0;
    for (let i = 0; i < births; i++) emit(rider, speed);
    for (const drop of drops) {
      if (drop.life <= 0) continue;
      drop.life -= dt;
      drop.vel.y -= 3.2 * dt;
      drop.sprite.position.addScaledVector(drop.vel, dt);
      const u = Math.max(drop.life, 0) / drop.age;
      drop.sprite.material.opacity = u * 0.8;
      const s = 0.12 + (1 - u) * 0.55;
      drop.sprite.scale.setScalar(s);
      if (drop.life <= 0) {
        drop.sprite.visible = false;
        drop.sprite.material.opacity = 0;
      }
    }
  }

  return { group, update };
}

import * as THREE from "three";
import { RoomEnvironment } from "three/addons/environments/RoomEnvironment.js";
import { createOcean } from "./ocean.js";
import { createSky, SUN_DIR } from "./sky.js";
import { createPelican } from "./pelican.js";
import { createSpray } from "./spray.js";
import { placeRider } from "./ride.js";

const canvas = document.querySelector("#view");

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
  powerPreference: "high-performance",
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color("#f3b48a");
scene.fog = new THREE.Fog("#f3b48a", 28, 78);

const camera = new THREE.PerspectiveCamera(34, window.innerWidth / window.innerHeight, 0.1, 400);
camera.position.set(-2.2, 2.4, 5.2);

const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.045).texture;
pmrem.dispose();

const sky = createSky();
scene.add(sky.dome, sky.clouds);

const ocean = createOcean();
scene.add(ocean.mesh);

const pelican = createPelican();
scene.add(pelican.root);

const spray = createSpray();
scene.add(spray.group);

const hemi = new THREE.HemisphereLight(0xc5ddff, 0xe0a070, 0.7);
scene.add(hemi);

const sun = new THREE.DirectionalLight(0xfff1d4, 3.4);
sun.position.copy(SUN_DIR).multiplyScalar(18);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.near = 2;
sun.shadow.camera.far = 36;
sun.shadow.camera.left = -6;
sun.shadow.camera.right = 6;
sun.shadow.camera.top = 6;
sun.shadow.camera.bottom = -6;
sun.shadow.bias = -0.0008;
scene.add(sun, sun.target);

const rim = new THREE.DirectionalLight(0xc9e4ff, 0.85);
rim.position.set(-6, 4, 8);
scene.add(rim);

const look = new THREE.Vector3();

function frame(t, dt) {
  const ride = placeRider(pelican.root, t);
  pelican.update(t, ride.turn);
  ocean.update(t, ride.originX);
  sky.update(t);
  spray.update(dt, pelican.root, ride.speed);

  sun.position.set(SUN_DIR.x * 18, SUN_DIR.y * 18, SUN_DIR.z * 18 + ride.z);
  sun.target.position.set(0, 0.6, ride.z);
  sun.target.updateMatrixWorld();

  const focusY = pelican.root.position.y;
  const focusZ = pelican.root.position.z;
  camera.up.set(0, 1, 0);
  camera.position.set(
    -1.55 + Math.sin(t * 0.23) * 0.12,
    focusY + 1.42 + Math.sin(t * 0.41) * 0.05,
    focusZ + 4.85,
  );
  look.set(0.25, focusY + 0.48, focusZ * 0.35);
  camera.lookAt(look);
}

let time = 0;
for (let i = 0; i < 50; i++) {
  time += 1 / 60;
  frame(time, 1 / 60);
}

function tick(now) {
  const dt = Math.min(0.033, (now - tick.last) / 1000 || 1 / 60);
  tick.last = now;
  time += dt;
  frame(time, dt);
  renderer.render(scene, camera);
  requestAnimationFrame(tick);
}
tick.last = performance.now();
requestAnimationFrame(tick);

window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

html,
body {
  margin: 0;
  height: 100%;
  background: #f3b48a;
  overflow: hidden;
}

#view {
  display: block;
  width: 100%;
  height: 100%;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 55%, rgba(62, 28, 16, 0.28) 100%);
}

