import * as THREE from "three";
import { quaternionFacing } from "./frame.js";
import { placeRider } from "./ride.js";
import { createPelican } from "./pelican.js";
import { writeWaveNormal, waveHeight, WAVE } from "./wave.js";

function assert(cond, msg) {
  if (!cond) {
    console.error("FAIL", msg);
    process.exitCode = 1;
  } else console.log("ok", msg);
}

const q = new THREE.Quaternion();
quaternionFacing(new THREE.Vector3(0, 0, -1), new THREE.Vector3(0, 1, 0), q);
const localFwd = new THREE.Vector3(0, 0, -1).applyQuaternion(q);
const localRight = new THREE.Vector3(1, 0, 0).applyQuaternion(q);
const localUp = new THREE.Vector3(0, 1, 0).applyQuaternion(q);
assert(localFwd.distanceTo(new THREE.Vector3(0, 0, -1)) < 1e-4, `canonical forward ${localFwd.toArray()}`);
assert(localRight.distanceTo(new THREE.Vector3(1, 0, 0)) < 1e-4, `canonical right ${localRight.toArray()}`);
assert(localUp.distanceTo(new THREE.Vector3(0, 1, 0)) < 1e-4, `canonical up ${localUp.toArray()}`);

quaternionFacing(new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 1, 0), q);
const f2 = new THREE.Vector3(0, 0, -1).applyQuaternion(q);
assert(f2.distanceTo(new THREE.Vector3(1, 0, 0)) < 1e-4, `+x forward maps local -z ${f2.toArray()}`);

const plane = new THREE.PlaneGeometry(2, 2, 1, 1);
plane.rotateX(-Math.PI / 2);
plane.computeVertexNormals();
assert(plane.attributes.normal.getY(0) > 0.9, `plane normal y ${plane.attributes.normal.getY(0)}`);

const n = new THREE.Vector3();
writeWaveNormal(0, 0, 0, n);
assert(n.y > 0.5, `wave normal up ${n.toArray()}`);

const rider = new THREE.Group();
const ride = placeRider(rider, 0);
console.log("t0 state", ride);
const rw = new THREE.Vector3(1, 0, 0).applyQuaternion(rider.quaternion);
const lw = new THREE.Vector3(-1, 0, 0).applyQuaternion(rider.quaternion);
console.log("wing heights R/L", rw.y.toFixed(3), lw.y.toFixed(3), "turn", ride.turn.toFixed(3));
assert(ride.turn > 0, "t0 turn is to the bird's right");
assert(rw.y < lw.y, "right wing lower than left on a right turn");

const face = new THREE.Vector3(0, 0, -1).applyQuaternion(rider.quaternion);
const travel = new THREE.Vector3(ride.vx, 0, ride.vz).normalize();
console.log("face", face.toArray(), "travel", travel.toArray(), "dot", face.dot(travel));
assert(face.dot(travel) > 0.9, "rider faces travel");

const pel = createPelican();
placeRider(pel.root, 0);
pel.update(0, ride.turn);
pel.root.updateMatrixWorld(true);
const tip = new THREE.Vector3();
const head = new THREE.Vector3();
pel.beakTip.getWorldPosition(tip);
pel.head.getWorldPosition(head);
const beakDir = tip.clone().sub(head).normalize();
const faceP = new THREE.Vector3(0, 0, -1).applyQuaternion(pel.root.quaternion);
console.log("beak", beakDir.toArray().map(v=>+v.toFixed(3)), "dot", +beakDir.dot(faceP).toFixed(3), "dy", +beakDir.y.toFixed(3));
console.log("head world", head.toArray().map(v=>+v.toFixed(3)), "tip", tip.toArray().map(v=>+v.toFixed(3)));
assert(beakDir.dot(faceP) > 0.75, "beak points mostly forward");

const pos = pel.wingGeoR.attributes.position;
let minZ = Infinity, maxZ = -Infinity, maxX = 0;
for (let i = 0; i < pos.count; i++) {
  minZ = Math.min(minZ, pos.getZ(i));
  maxZ = Math.max(maxZ, pos.getZ(i));
  maxX = Math.max(maxX, pos.getX(i));
}
console.log("wing z", minZ.toFixed(3), maxZ.toFixed(3), "span", maxX.toFixed(3));
assert(minZ < -0.05 && maxZ > 0.02, "wing has leading (-z) and trailing (+z)");
assert(maxX > 1.2, "wing spans outward");

// displacement
const a = placeRider(rider, 0);
const b = placeRider(rider, 2);
assert(Math.abs(b.originX - a.originX) > 1, `scroll moves ${b.originX - a.originX}`);

// slope along face
console.log("phase", WAVE.phaseOnFace, "height", waveHeight(a.originX, 0, 0).toFixed(3));
const e = 0.05;
const slope = (waveHeight(a.originX + e, 0, 0) - waveHeight(a.originX - e, 0, 0)) / (2 * e);
console.log("slope dy/dx", slope.toFixed(3), "deg", (Math.atan(slope)*180/Math.PI).toFixed(1));

// board nose: find mesh
let board = null;
pel.root.traverse(o => { if (o.geometry && o.geometry.boundingBox === undefined && o.geometry.type === "ExtrudeGeometry") {} });
const boardMesh = pel.root.children.find(c => c.geometry && c.geometry.type === "ExtrudeGeometry");
boardMesh.geometry.computeBoundingBox();
const bb = boardMesh.geometry.boundingBox;
console.log("first extrude bb", bb.min.toArray().map(v=>+v.toFixed(2)), bb.max.toArray().map(v=>+v.toFixed(2)));
EOF

