function scan(label, fn) {
  let best = null;
  const rows = [];
  for (let i = 0; i <= 80; i++) {
    const p = -0.2 + (i/80)*2.2;
    const e = 0.015;
    const y = fn(p);
    const s = (fn(p+e)-fn(p-e))/(2*e);
    const deg = Math.atan(s)*180/Math.PI;
    if (!best || s > best.s) best = { p, s, deg, y };
    if (i % 8 === 0) rows.push(`${p.toFixed(2)} y ${y.toFixed(2)} deg ${deg.toFixed(1)}`);
  }
  console.log("\n"+label, "max", best);
  console.log(rows.join("\n"));
}
const A = 1.15;
scan("harmonic 0.55", (p) => (Math.sin(p)+0.55*Math.sin(2*p+1.1))*A);
scan("pow", (p) => Math.sign(Math.sin(p)) * Math.pow(Math.abs(Math.sin(p)), 0.65) * A);
scan("lip", (p) => {
  const base = Math.sin(p);
  const lip = Math.exp(-Math.pow((p - 1.05)/0.45, 2)) * 0.55;
  return (base + lip) * A;
});
EOF

