import * as THREE from "three";
import { placeRider } from "./ride.js";
import { createPelican } from "./pelican.js";
import { waveHeight, WAVE } from "./wave.js";

function assert(cond, msg) {
  if (!cond) { console.error("FAIL", msg); process.exitCode = 1; }
  else console.log("ok", msg);
}
const rider = new THREE.Group();
const ride = placeRider(rider, 0);
const rw = new THREE.Vector3(1, 0, 0).applyQuaternion(rider.quaternion);
const lw = new THREE.Vector3(-1, 0, 0).applyQuaternion(rider.quaternion);
console.log("R/L", rw.y.toFixed(3), lw.y.toFixed(3), "turn", ride.turn.toFixed(3));
assert(rw.y < lw.y - 0.02, "right wing lower on right turn");
const face = new THREE.Vector3(0, 0, -1).applyQuaternion(rider.quaternion);
const travel = new THREE.Vector3(ride.vx, 0, ride.vz).normalize();
assert(face.dot(travel) > 0.85, `faces travel ${face.dot(travel).toFixed(3)}`);

const pel = createPelican();
placeRider(pel.root, 0);
pel.update(0, ride.turn);
pel.root.updateMatrixWorld(true);
const tip = new THREE.Vector3();
const head = new THREE.Vector3();
const root = new THREE.Vector3();
pel.beakTip.getWorldPosition(tip);
pel.head.getWorldPosition(head);
pel.root.getWorldPosition(root);
const beakDir = tip.clone().sub(head).normalize();
const faceP = new THREE.Vector3(0, 0, -1).applyQuaternion(pel.root.quaternion);
console.log("beak", beakDir.toArray().map(v=>+v.toFixed(3)), "dot", +beakDir.dot(faceP).toFixed(3));
console.log("head-root", head.clone().sub(root).toArray().map(v=>+v.toFixed(3)));
console.log("tip-root", tip.clone().sub(root).toArray().map(v=>+v.toFixed(3)));
assert(beakDir.dot(faceP) > 0.8, "beak forward");

const x = ride.originX;
const e = 0.05;
const slope = (waveHeight(x+e, 0, 0) - waveHeight(x-e, 0, 0)) / (2*e);
console.log("height", waveHeight(x,0,0).toFixed(3), "dy/dx", slope.toFixed(3), "deg", (Math.atan(slope)*180/Math.PI).toFixed(1), "speed", ride.speed.toFixed(2));

// left turn at later time when vz < 0
let tNeg = null;
for (let t = 0; t < 8; t += 0.05) {
  const r = placeRider(rider, t);
  if (r.turn < -0.15) { tNeg = t; break; }
}
const rideL = placeRider(rider, tNeg);
const rw2 = new THREE.Vector3(1,0,0).applyQuaternion(rider.quaternion);
const lw2 = new THREE.Vector3(-1,0,0).applyQuaternion(rider.quaternion);
console.log("left turn", rideL.turn.toFixed(3), "R/L y", rw2.y.toFixed(3), lw2.y.toFixed(3));
assert(lw2.y < rw2.y - 0.02, "left wing lower on left turn");
EOF

