import http from "http";
import fs from "fs";
import path from "path";
import { spawn } from "child_process";

const root = "<vol>/dev/art-crit-runs/2026-10-17-090728-surfing-pelican/grok-4.7-gb-low-20261017-090728/work";
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json" };
const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  let rel = decodeURIComponent(url.pathname);
  if (rel === "/") rel = "/index.html";
  const file = path.join(root, rel);
  if (!file.startsWith(root)) { res.writeHead(403); res.end(); return; }
  fs.readFile(file, (err, data) => {
    if (err) { res.writeHead(404); res.end("no"); return; }
    res.writeHead(200, { "Content-Type": types[path.extname(file)] || "application/octet-stream" });
    res.end(data);
  });
});
await new Promise((resolve) => server.listen(8765, "127.0.0.1", resolve));
const chrome = "/Applications/Google Chrome";
const out = "/tmp/pelican-shot.png";
const args = [
  "--headless=new",
  "--disable-gpu",
  "--hide-scrollbars",
  "--force-device-scale-factor=1",
  "--virtual-time-budget=3500",
  "--window-size=1280,720",
  `--screenshot=${out}`,
  "http://127.0.0.1:8765/",
];
const code = await new Promise((resolve) => {
  const p = spawn(chrome, args, { stdio: "inherit" });
  p.on("exit", resolve);
});
server.close();
console.log("chrome exit", code, "shot", fs.existsSync(out), fs.existsSync(out) ? fs.statSync(out).size : 0);
